  sha=${br#* }; br=${br% *}
  echo "################ PR #$n  ($br)"
  gh api "repos/Late-bloomer420/miTch/commits/$sha/check-runs" \
    --jq '.check_runs[]|select(.name=="Entire Gates")|"status=\(.status) conclusion=\(.conclusion)\n\(.output.summary)"'
