import json,sys
raw=sys.stdin.read()
try: d=json.loads(raw)
except Exception: print('FINDINGS READ FAILED:', raw[:400]); sys.exit()
print('counts:', d['counts'])
order=['high','medium','low']
for f in sorted(d['findings'], key=lambda x: order.index(x['severity']) if x['severity'] in order else 9):
