    print(f\"\n[{f['severity'].upper()} conf={f['confidence']} status={f['status']}] {l.get('filePath')}:{l.get('startLine')}-{l.get('endLine')}\n{f['body']}\")
if d.get('has_more'): print('!! MORE FINDINGS NOT SHOWN (has_more=true)')
